/-- The outcome in a lower-bound experiment is genuinely Bernoulli. -/
def BernoulliOutcomeLaw (P : ClampLaw J) : Prop :=
  ∀ᵐ o ∂P.dataMeasure, o.Y = 0 ∨ o.Y = 1

