/-- A canonical observation with the specified design and dummy outcome. -/
def clampDesignLift {J : ℕ} (d : Fin J × ℝ) : ClampObs J :=
  ⟨d.1, d.2, 0⟩

/-- Extend the model's regression from its declared dose interval by zero. -/
def clampRegressionExtension (P : ClampLaw J) (d : Fin J × ℝ) : ℝ :=
  if d.2 ∈ Set.Icc (0 : ℝ) 1 then P.mu d.1 d.2 else 0

/-- Worst-case expected length of any given confidence procedure. -/
def confidenceWorstLength (J n : ℕ)
    (beta kappa L cminus cplus pmin : ℝ) (C : ConfidenceProcedure n J) : ℝ≥0∞ :=
  sSup {v : ℝ≥0∞ | ∃ P : ClampLaw J,
    ClampModel P beta kappa L cminus cplus pmin ∧
    v = ∫⁻ z, intervalLengthENNReal (C z) ∂iidProduct P n}

