/-- The canonical product law of the observed sample. -/
def iidProduct (P : ClampLaw J) (n : ℕ) : Measure (Fin n → ClampObs J) :=
  Measure.pi (fun _ : Fin n => P.dataMeasure)

/-- Uniform population-Gram constant. -/
def lambdaStar (ell : ℕ) (kappa cminus cplus : ℝ) : ℝ :=
  (cminus / cplus) * sInf {q : ℝ | ∃ rho : ℝ, 0 ≤ rho ∧
    q = quadraticMin (refMomentMatrix ell kappa rho)}

/-- Unit local-window weight in a fixed stratum. -/
def localWindowWeight {J : ℕ} (x : Fin J) (delta h : ℝ) (o : ClampObs J) : ℝ :=
  if o.X = x ∧ scaledDose delta h o ∈ Set.Icc (0 : ℝ) 1 then 1 else 0

/-- The common `(X,A)` law of every minimax witness. -/
def minimaxDesignMeasure (J : ℕ) (kappa : ℝ) : Measure (Fin J × ℝ) :=
  (minimaxStratumMeasure J).prod (minimaxTreatmentMeasure kappa)

/-- Uniform probability law on the finite stratum space. -/
def minimaxStratumMeasure (J : ℕ) : Measure (Fin J) :=
  ProbabilityTheory.uniformOn Set.univ

/-- Monomial basis `(1,u,...,u^ell)`. -/
def monomialVec (ell : ℕ) (u : ℝ) : Fin (ell + 1) → ℝ :=
  fun j => u ^ (j : ℕ) -- @realizes v_ell(monomial basis through degree ell)

/-- Width-`h`, height-`h` localized Bernoulli alternative for beta one. -/
def oneCellRegression1 (delta h a : ℝ) : ℝ :=
  1 / 2 + h * oneCellTent delta h a

/-- Product chi-squared divergence used by the same-class witnesses. -/
def productChiSq (P Q : ClampLaw J) (n : ℕ) : ℝ :=
  Causalean.Stat.chiSqDiv (iidProduct P n) (iidProduct Q n)

/-- Smallest quadratic-form value on the Euclidean unit sphere. -/
def quadraticMin {d : ℕ} (A : Matrix (Fin d) (Fin d) ℝ) : ℝ :=
  sInf {q : ℝ | ∃ z : Fin d → ℝ,
    (∑ i, (z i) ^ 2) = 1 ∧ q = matrixQuadratic A z}

